    say_hello_to_habitus: "HABITUS'A MERHABA DE!",
    q1_text: "Yeni bir güne uyandın ve hedeflerine bakıyorsun. İçinden geçen ilk düşünce nedir?",
    q1_opt_1: "Hadi dünyayı fethedelim! Bugün harika olacak! ✨",
    q1_opt_2: "Bunu bugün bitirmem LAZIM. Tembelliğe tahammülüm yok!",
    q1_opt_3: "Hayat bir oyun, sakin kalıp akışta süzülelim...",
    q1_opt_4: "Yine mi yapılacaklar listesi... Neyse, bakarız.",
