    q1_opt_2: "Ich MUSS das heute erledigen. Keine Faulheit!",
    q1_opt_3: "Das Leben ist ein Spiel, bleiben wir ruhig...",
    q1_opt_4: "Schon wieder eine To-Do-Liste... Na ja, egal.",
    q2_text: "Du hast eine Gewohnheit verpasst. Wie sollte Habitus reagieren?",
    q2_opt_1: "Sagen: 'Keine Sorge, morgen kommen wir stärkere zurück!' ❤️",
    q2_opt_2: "Mich streng für meine Faulheit ausschimpfen!",
    q2_opt_3: "Sich über mich lustig machen, um mich anzuspornen!",
    q2_opt_4: "Mich daran erinnern, tief durchzuatmen.",
    q3_text: "Welcher Ansatz motiviert dich am meisten?",
