    q2_opt_1: "说 '没关系，明天我们会更强！' ❤️",
    q2_opt_2: "因为我的懒惰严厉训斥我！",
    q2_opt_3: "嘲笑我，好让我激发斗志！",
    q2_opt_4: "提醒我深呼吸，这只是一时的波折。",
    q3_text: "什么样的方式最能激发你的动力？",
    q3_opt_1: "温暖、开朗且友善的伙伴能量。",
    q3_opt_2: "严格、施压且零容忍的纪律。",
    q3_opt_3: "幽默、讽刺且略带嘲弄的点评。",
    q3_opt_4: "富有智慧、哲理且深刻的建议。",
    q4_text: "什么是你理想的人生哲学？",
    q4_opt_1: "微笑、去爱，享受当下！ 🌟",
    q4_opt_2: "战斗并获胜！不突破极限的人就会落后。",
    q4_opt_3: "让心灵平静，与宇宙合一，寻找宁静。",
    q4_opt_4: "别再为一切发愁，世界本就很奇特。",
    q5_text: "当你的同志陷入懒惰危机、准备放弃时该怎么办？",
    q5_opt_1: "他立即握住我的手说：“你能行的！”应该支持。 ❤️",
    q5_opt_2: "他必须大喊大叫并摇晃我才能站起来并移动！ ⚡",
    q5_opt_3: "他应该说“我知道你无论如何也做不到”，然后激怒我。 😏",
    q5_opt_4: "他应该静静地等待，等待我找到自己内心的力量。 🧘",
    q6_text: "当你成功完成一个困难的习惯时，习惯应该如何祝贺你？",
    q6_opt_1: "他应该爆炸五彩纸屑并热情地大喊！ 🎉",
    q6_opt_2: "他自豪地点点头，说道：“干得好，士兵，不要停下来！”应该说。 🫡",
    q6_opt_3: "“哇，奇迹发生了！”并幽默地祝贺他。 😎",
    q6_opt_4: "他应该以默默而深刻的赞许来欣赏我的智慧。 ☯️",
    q7_text: "您希望日常对话中有多少幽默和讽刺？",
    q7_opt_1: "我不需要任何讽刺，只要实证和真诚！",
    q7_opt_2: "让他甜一点，硬一点，时不时就能开点玩笑。",
    q7_opt_3: "要有足够的黑色幽默和残酷的讽刺！",
    q7_opt_4: "不要使用不必要的词语，说话冷静、简洁。",
    q8_text: "Habitus 与您沟通的总体语气应该是什么样的？",
    q8_opt_1: "一个充满爱心、充满活力和激励人心的好朋友！",
    q8_opt_2: "一位纪律严明、毫不妥协、独裁的教练！",
    q8_opt_3: "圣人大师，指导老师。",
    q8_opt_4: "一个无忧无虑的朋友，有着悠闲的聚会风格。",
